    import time

    LANGUAGE_WRAPPER = 'In the Cartesian plane, let B = ({b_x}, {b_y}) and C = ({c_x}, {c_y}), and let D be the point on segment BC for which BD:DC = {m_ratio}:{n_ratio}. Consider all points A = (p, q) such that triangle ABC has area {area_t}, and the line AD has slope {slope_num}/{slope_den} (in lowest terms with {slope_den} > 0). Among all such points A, determine the largest possible value of {lin_coef_x}·p + {lin_coef_y}·q.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
from math import gcd
# Helper to pick coprime slope
def coprime(a,b):
    return gcd(abs(a),abs(b)) == 1
for _ in range(200):
    # Generate B and C
    bx = rng.randint(-10, 20)
    by = rng.randint(-10, 20)
    # ensure C different and not too close
    while True:
        cx = rng.randint(-10, 20)
        cy = rng.randint(-10, 20)
        if (cx,cy) != (bx,by):
            break
    dx = cx - bx
    dy = cy - by
    # choose m,n positive for internal division
    m = rng.randint(1, 6)
    n = rng.randint(1, 6)
    # choose slope as rational with positive denominator, not parallel to BC
    # slope = s_num / s_den
    # ensure dx*s_num - dy*s_den != 0 (not parallel to BC)
    attempts = 0
    while True:
        s_den = rng.randint(1, 7)
        s_num = rng.randint(-7, 7)
        if s_num == 0 and rng.random() < 0.3:
            # allow zero slope sometimes
            pass
        if coprime(s_num, s_den) and (dx * s_num - dy * s_den) != 0:
            break
        attempts += 1
        if attempts > 200:
            # reset outer
            break
    if attempts > 200:
        continue
    # linear objective coefficients, avoid trivial U=0
    while True:
        u = rng.randint(-4, 4)
        v = rng.randint(-4, 4)
        if not (u == 0 and v == 0) and (u * s_den + v * s_num) != 0:
            break
    # choose a reasonable positive area
