    def verifier(assign):
# Recompute, validate constraints, return (True, answer_str)
# We'll compute the maximum of u*p + v*q under constraints
from fractions import Fraction
try:
    bx = int(assign['b_x']); by = int(assign['b_y'])
    cx = int(assign['c_x']); cy = int(assign['c_y'])
    m = int(assign['m_ratio']); n = int(assign['n_ratio'])
    T = int(assign['area_t'])
    s_num = int(assign['slope_num']); s_den = int(assign['slope_den'])
    u = int(assign['lin_coef_x']); v = int(assign['lin_coef_y'])
except Exception:
    # invalid types
    return (False, None)
# Basic validation
if (bx,by) == (cx,cy):
    # B and C must be distinct
    return (False, None)
if m <= 0 or n <= 0:
    # internal division required
    return (False, None)
if s_den <= 0:
    return (False, None)
if T <= 0:
    return (False, None)
if u == 0 and v == 0:
    return (False, None)
dx = cx - bx; dy = cy - by
# avoid AD parallel to BC
K1 = dx * s_num - dy * s_den
if K1 == 0:
    return (False, None)
# avoid objective being constant along AD
U = u * s_den + v * s_num
if U == 0:
    return (False, None)
# Compute point D on BC with BD:DC = m:n -> D = (n*B + m*C)/(m+n)
denom = m + n
Dx = Fraction(n * bx + m * cx, denom)
Dy = Fraction(n * by + m * cy, denom)
# K0 = dx*(Dy - by) - dy*(Dx - bx)
K0 = Fraction(dx, 1) * (Dy - Fraction(by, 1)) - Fraction(dy, 1) * (Dx - Fraction(bx, 1))
# Solve for t in K0 + t*K1 = ± 2T
# Compute t1 for +2T and t2 for -2T
t1 = (Fraction(2*T, 1) - K0) / Fraction(K1, 1)
t2 = (Fraction(-2*T, 1) - K0) / Fraction(K1, 1)
# A(t) = D + t*(s_den, s_num)
def A_of_t(t):
    Ax = Dx + t * Fraction(s_den, 1)
    Ay = Dy + t * Fraction(s_num, 1)
    return Ax, Ay
A1x, A1y = A_of_t(t1)
A2x, A2y = A_of_t(t2)
# They must be distinct
if A1x == A2x and A1y == A2y:
    return (False, None)
# Evaluate objective
F1 = Fraction(u,1)*A1x + Fraction(v,1)*A1y
F2 = Fraction(u,1)*A2x + Fraction(v,1)*A2y
Fmax = F1 if F1 >= F2 else F2
# Return as simplified fraction string
if Fmax.denominator == 1:
    ans = str(Fmax.numerator)
else:
    # Properly sign the fraction a/b
    num = Fmax.numerator; den = Fmax.denominator
    ans = f"{num}/{den}"
return True, ans


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

